INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(61800, 0, 618, 0, 0, 0, 'Winterspring', 'Winterspring is a high valley of snow and ice in the mountains of northern Kalimdor, east of Felwood, north of Azshara and northeast of Mount Hyjal. Most travelers reach it through the tunnels of Timbermaw Hold. Long ago the night elves raised the city of Kel''Theril here, and beside its ruins the cursed spirits of Highborne still drift over a frozen lake. In the Third War Tyrande Whisperwind and Malfurion Stormrage fought across these snows and woke the Druids of the Talon from their barrow dens. Today the goblins of the Steamwheedle Cartel keep the trading post of Everlook at the crossroads of the valley, and night elves hold Starfall Village to its northwest. Frostsabers prowl the northern heights, maddened wildkin guard old sacred places, and the Winterfall furbolgs have turned savage. Blue dragons lair in the caverns of Mazthoril, frost giants hold a canyon in the south, and beyond it, in Darkwhisper Gorge, demons stand between the valley and the heights of Hyjal.', 'warcraft.wiki.gg/wiki/Winterspring (geography: east of Felwood, north of Azshara, northeast of Hyjal, access through Timbermaw Hold; Kel''Theril and the Sundering; Third War: Tyrande and Malfurion awakened the Druids of the Talon in the Barrow Dens; Darkwhisper demons guarding an entrance to Mount Hyjal); warcraft.wiki.gg/wiki/Everlook (Steamwheedle trading post at the crossroads); warcraft.wiki.gg/wiki/Starfall_Village; quest 5244 description; quest 5121 description; quest 4842 reward text; quest 5981 description; DB spawns by subzone (zone_areas.py); warcraft.wiki.gg/wiki/Ruins_of_Kel''Theril (a great night elven city); warcraft.wiki.gg/wiki/Darkwhisper_Gorge (nonfunctional Hyjal entrance pre-Cataclysm)'),
(61801, 1, 618, 1, 0, 0, 'Frostfire Hot Springs', 'At the far western end of Winterspring, close to the mouth of Timbermaw Hold, steaming pools break through the snow. No volcano lies anywhere near them, and that riddle has drawn the dwarf Donova Snowden, who keeps watch beside one of the springs and has found that their water has strange qualities. She suspects a darker cause than fire beneath the earth: the demons of Darkwhisper Gorge, far to the south, whose presence she believes is warming the land. The Winterfall furbolgs are drawn to the springs as well. Their pathfinders and den watchers guard the two larger pools fiercely and drive off anyone who comes near.', 'warcraft.wiki.gg/wiki/Frostfire_Hot_Springs (far western end, Donova suspects Darkwhisper demons); warcraft.wiki.gg/wiki/Donova_Snowden (dwarf); quest 980 description (no volcanoes anywhere near); quest 4842 description and reward text; quest 5082 description (Winterfall protective of the two larger springs); DB spawns in area 2246: Winterfall Den Watcher, Winterfall Pathfinder; Donova 9298 at 6395,-2536 just outside the subzone'),
(61802, 1, 618, 2, 0, 0, 'Timbermaw Post', 'Southeast of the road that runs from the hot springs toward the heart of Winterspring lies Timbermaw Post, a small furbolg camp. Its name suggests that the Timbermaw of the nearby hold once kept it, but the camp now belongs wholly to the Winterfall tribe, whose den watchers and pathfinders stand guard there while owlbeasts and shardtooth bears roam the slopes around it. Salfa, who guards the Winterspring gate of the hold, remembers that the Winterfall were once allies of the Timbermaw, until the strange demands of a high chief turned them against everyone they met.', 'warcraft.wiki.gg/wiki/Timbermaw_Post (southeast of the road from the hot springs, west of Lake Kel''Theril, held by the Winterfall); npc_text 4396 (Salfa: the Winterfall were once our allies, driven by the strange demands of their high chief); DB spawns in area 2243: Winterfall Den Watcher x9, Winterfall Pathfinder x9, Shardtooth Bear, Ragged Owlbeast'),
(61803, 1, 618, 3, 0, 0, 'Lake Kel''Theril', 'In the center of Winterspring lies Lake Kel''Theril, frozen hard beneath the mountain wind. Long ago Highborne sorcerers stole a sacred relic, the Crystal of Zin-Malor, from a temple in Eldarath, hoping to siphon its power and become greater still. Their ritual failed. The crystal shattered in a tremendous explosion, and its pieces were driven deep beneath the ice of the lake. The thieves were cursed to remain where they had worked their folly, and their suffering, anguished spirits still drift over the frozen water, searching for fragments of the very thing that doomed them. Chimaerae, bears and owlbeasts hunt along the shore.', 'quest 5244 description (cursed race bound to the place of the ritual, relic shattered and driven below the ice); quest 5245 description (spirits still search for pieces of the relic); quest 5246 (Crystal of Zin-Malor); warcraft.wiki.gg/wiki/Winterspring (Highborne stole the Crystal of Zin-Malor from a temple in Eldarath); warcraft.wiki.gg/wiki/Lake_Kel''Theril (small frozen lake in central Winterspring); DB spawns in area 2251: Suffering Highborne, Anguished Highborne, Highborne Relic Fragment objects, Chillwind Chimaera, Shardtooth Bear, Ragged Owlbeast'),
(61804, 1, 618, 4, 0, 0, 'The Ruins of Kel''Theril', 'On the shore of Lake Kel''Theril lie the remains of a great Highborne city, broken in the Great Sundering ten thousand years ago. Among its fallen stones walk the spirits of the Highborne who died here, suffering and anguished, still bound by the curse of the crystal their people stole. Nearly all of them are lost in their own misery and cannot be reached. One alone, a remorseful spirit, has come to understand the error of what was done so long ago, though it knows the past cannot be undone. The night elf Ranshalla has studied the carvings on these stones and believes they hold the incantations of an ancient altar of Elune.', 'warcraft.wiki.gg/wiki/Ruins_of_Kel''Theril (night elven city destroyed in the Great Sundering, haunted by Highborne); npc_text 4635 (Remorseful Highborne: the past cannot be undone); quest 5252 description (the highborne here are clouded by their own misery; I realize the error); quest 4901 description (incantations carved into the stone in the ruins); npc_text 3866 (Ranshalla explored the ruins); DB spawns in area 2252: Suffering and Anguished Highborne, Remorseful Highborne 10684; warcraft.wiki.gg/wiki/Ruins_of_Kel''Theril (pre-Cataclysm: Highborne spirits; high elf ghosts and wretched are Cataclysm additions)'),
(61805, 1, 618, 5, 0, 0, 'Starfall Village', 'Starfall Village is a small night elf settlement on the main road between Everlook and Frostsaber Rock, and the only Alliance outpost in Winterspring. A lodge and a smaller house shelter sellers of food, goods and trade supplies, and the village keeps the old Ban''Thallow Barrow Den. Wynd Nightchaser spends most of his days here and knows a great deal about the valley and its secrets. A dwarf has come as well, Jaron Stoneshaper of the Explorers'' League, who hunts the magical artifacts said to lie in Winterspring, most of them fiercely guarded. He rests here now, after the wildkin chased him from his camp.', 'warcraft.wiki.gg/wiki/Starfall_Village (main road between Everlook and Frostsaber Rock, only Alliance settlement, Ban''Thallow Barrow Den, lodge, residents); quest 5249 description (Wynd spends most of his time in Starfall and knows a lot about the area); npc_text 4573 (Jaron: Explorers'' League hunting artifacts, most highly guarded); quest 6604 description (a survivor of the attack is resting at Starfall Village); quest 4864 (Jaron at the lodge); DB spawns in area 2253: Wynd Nightchaser, Jaron Stoneshaper, Grum Redbeard, Lyranne Feathersong, Natheril Raincaller, Syurana; subnames: Lyranne Feathersong Food & Drink, Natheril Raincaller General Goods, Syurana Trade Supplies'),
(61806, 1, 618, 6, 0, 0, 'Frostsaber Rock', 'In the far north of Winterspring a great tor juts above the snow, and around it gather the frostsabers, the most feral and hardest to tame of all the great cats. Their matriarch is Shy-Rotam, whose stone stands among the pride. About four thousand years ago Tyrande Whisperwind saved the frostsaber queen from rampaging giants, and since that day the cats have been allies of the night elves. Huntresses, stalkers and pride watchers roam among the cubs, and a great cat called Rak''shiri hunts among them. At the top of the rock the night elf Rivern Frostwind and his companion Glacier patiently train frostsabers to carry riders.', 'warcraft.wiki.gg/wiki/Frostsaber_Rock (large jutting tor in the north; Rivern at the apex); quest 5981 description (Tyrande saved the frostsaber queen about 4,000 years ago); quest 5056 description (Shy-Rotam leads the cats; her stone); npc_text 3854 (most feral and difficult to subdue of all the sabers); DB spawns in area 2241: Frostsaber, Frostsaber Cub, Huntress, Stalker, Pride Watcher, Rak''shiri 10200, Rivern 10618, Glacier 10619; gameobject Stone of Shy-Rotam 177684 resolves to 2241'),
(61807, 1, 618, 7, 0, 0, 'Everlook', 'Everlook is a trading post of the Steamwheedle Cartel, built where the main trade routes of Winterspring meet. Like the Cartel''s other towns it is neutral ground, and its goblin bruisers have no patience for anyone who spills blood within its walls. An inn, a market and the only bank in the valley serve travelers of every race. The town draws curious company: Gregor Greystone speaks for the Argent Dawn before the local governance, Malyfous Darkhammer represents the Thorium Brotherhood, a troll witch doctor makes lucky charms, and a stern tauren sets trials for the bold.', 'warcraft.wiki.gg/wiki/Everlook (Steamwheedle trading post, crossroads of trade routes, only bank, last settlement before Hyjal Summit, neutral, Thorium Brotherhood); creature_text 11190 (Everlook Bruiser: You dare spill blood on neutral ground?); quest 6028 description (Gregor represents the Argent Dawn to the local governance of Everlook); npc_text 3673 (Malyfous); DB spawns in area 2255: Witch Doctor Mau''ari, Storm Shadowhoof, Innkeeper Vizzie, Izzy Coppergrab, Auctioneer Grizzlin; creature_template 10637 subname The Thorium Brotherhood'),
(61808, 1, 618, 8, 0, 0, 'Mazthoril', 'Mazthoril is a deep cavern of ice in central Winterspring, near Lake Kel''Theril and Everlook, and the home of the blue dragonflight in these lands. Cobalt wyrmkin, scalebanes and mageweavers guard its frozen halls among whelps, broodlings and spell eaters, while the drakes Spellmaw, Manaclaw and Scryer keep watch and the blue General Colbatann stalks its passages. At the heart of it all dwells Haleh, the matron protectorate of the flight. Her chamber at the cavern''s peak is reached only by magic: cobalt runes set into the icy floor carry those who hold one of the flight''s scales up to her.', 'warcraft.wiki.gg/wiki/Mazthoril (deep icy cavern near Lake Kel''Theril and Everlook, home of the blue dragonflight, Haleh at the peak reached by a portal rune, drakes Spellmaw, Manaclaw, Scryer, General Colbatann); quest 5160 description (cobalt runes on the icy floors; hold a scale and stand on a rune to be transported to Haleh); DB spawns in area 2245: Cobalt Wyrmkin, Scalebane, Mageweaver, Whelp, Broodling, Spell Eater, Spellmaw, General Colbatann, Haleh; gameobject Rune of Mazthoril'),
(61809, 1, 618, 9, 0, 0, 'Ice Thistle Hills', 'Southeast of Everlook rise the Ice Thistle Hills, the country of the Ice Thistle yeti. They make their home in a cave high in the hills and roam the snowy slopes around it, and their great patriarchs and matriarchs carry the largest horns of their kind. Chillwind chimaerae and shardtooth bears hunt the same ground. The yeti know little peace, for their thick fur and pristine horns are prized in Everlook, where Umi Rumplesnicker once needed both to build a mechanical yeti of her own. A blue dragon named Azurous roams the hills as well.', 'warcraft.wiki.gg/wiki/Ice_Thistle_Hills (southeast of Everlook, yeti cave high in the hill); quest 3783 description (thick yeti fur, to the southeast); quest 977 description (patriarchs and matriarchs have the largest horns; cave to the southeast); warcraft.wiki.gg/wiki/Mazthoril (Azurous watches for threats); DB spawns in area 2247: Ice Thistle Yeti, Matriarch, Patriarch, Chillwind Chimaera, Shardtooth Mauler, Azurous 10202'),
(61810, 1, 618, 10, 0, 0, 'Winterfall Village', 'Far to the east lies Winterfall Village, the home of the Winterfall furbolgs. The tribe was never known for aggression, yet its ursa, shamans and den watchers now fall upon nearly anything that comes near. The change began with the strange demands of High Chief Winterfall, who keeps to the mouth of a cave at the edge of the village and carries a crude log that no one can easily read. His people drink a glowing firewater brewed from corrupted ooze, and the Timbermaw came to learn that a demon named Xandivious lurked behind their madness. The fierce Grizzle Snowpaw prowls the camp, and yeti and shardtooth bears roam nearby.', 'quest 5121 description (not a normally aggressive tribe, under orders from their chief; head east to Winterfall Village); npc_text 4396 (strange demands of their high chief); quest 5123 description (crude log); quest 5083 and 5087 (glowing green liquid; toxic substance purified in spring water); felwood.json Gorn One Eye entry (Xandivious, lured out at the cave mouth), mentioned only; DB spawns in area 2244: Winterfall Ursa, Shaman, Den Watcher, High Chief Winterfall 10738 at 6725,-5277, cave mouth spell focus object 180673, Grizzle Snowpaw 10199, Ice Thistle yeti, Shardtooth Mauler'),
(61811, 1, 618, 11, 0, 0, 'The Hidden Grove', 'In the northeast of Winterspring a forested crater lies hidden behind high cliffs on every side. The only ordinary way in is a cave in the southeastern face of the ridge, though a bold climber might risk the drop from the cliffs above. Within lies a haunt of moontouched owlbeasts, the hostile wildkin of the northern valley, which are fiercer than their kin elsewhere in Winterspring. A few crazed and berserk owlbeasts live among them, and more of their moontouched kind roam the snowy ground beyond the cliffs.', 'warcraft.wiki.gg/wiki/The_Hidden_Grove (forested crater in the northeast, surrounded by cliffs, single cave entrance on the southeastern face, hostile moonkin); quest 4741 description (in the northern areas the wildkin grow even more ferocious; hunt the moontouched owlbeasts and explore their area); quest 4521 description (wildkin guard secrets of the night elves); DB spawns in area 2242: Moontouched Owlbeast x3, Crazed Owlbeast, Berserk Owlbeast; DB: northern Moontouched Owlbeast spawns (x 7350 to 7800) resolve to 2242 and the surrounding area 618; southern ones to Owl Wing Thicket and Dun Mandarr; warcraft.wiki.gg/wiki/The_Hidden_Grove (dropping down from the top possible but dangerous)'),
(61812, 1, 618, 12, 0, 0, 'Owl Wing Thicket', 'Owl Wing Thicket is a series of caves along a ridge in southern Winterspring, overrun by crazed, berserk and moontouched owlbeasts. Horde runners report that these wildkin seem to have gone mad from exposure to the very thing they guard. At the top of the ridge lies an ancient altar of the goddess Elune, sealed until torches in the caves are lit and old incantations spoken over it. At the foot of the ridge waits the night elf Ranshalla, a colleague of the scholar Erelas Ambersky, fresh from studying the Ruins of Kel''Theril and determined to learn why the wildkin defend this place so fiercely.', 'warcraft.wiki.gg/wiki/Owl_Wing_Thicket (series of caves in southern Winterspring, berserk, moontouched and crazed owlbeasts); quest 4721 description (series of small caves in the south; creatures gone mad from exposure to what they protect); quest 4901 description (altar of Elune at the top of the ridge, five torches); npc_text 3866 (Ranshalla back from Kel''Theril, investigating the wildkin up the ridge); quest 979 description; DB spawns in area 2250: Ranshalla 10300, Altar of Elune 177404, Fire of Elune objects, Moontouched/Crazed/Berserk Owlbeast'),
(61813, 1, 618, 13, 0, 0, 'Dun Mandarr', 'Dun Mandarr is a small camp beside an icy cavern in southeastern Winterspring, set up by the dwarf Jaron Stoneshaper of the Explorers'' League. It did not last. Soon after Jaron unearthed a blue-feathered amulet at his dig site, bloodthirsty wildkin fell upon the camp, smashing his crates and wagon and chasing him away, and he fears a friend of his was not so lucky. Owlbeasts and screeching owls now haunt the wreckage, and what remains of his tools lies half buried in the snow. The beasts seemed to want the amulet above all else, and Jaron still wonders why they defended it so fiercely.', 'warcraft.wiki.gg/wiki/Dun_Mandarr (small camp near an icy cavern in the southeast, set up by Jaron, overrun by moonkin); quest 4861 description (chased from camp by wildkin, a buddy not as lucky, amulet unearthed at the dig site); quest 4863 description (crate smashed open, abandoned wagon); quest 4864 description and reward text (supplies half-buried in snow; why the wildkin defended it); DB objects in area 2248: Jaron''s Wagon, Damaged Crate, Jaron''s Supplies; spawns Winterspring Screecher x12, Crazed and Moontouched Owlbeast'),
(61814, 1, 618, 14, 0, 0, 'Frostwhisper Gorge', 'Frostwhisper Gorge is a deep canyon in the south of Winterspring, held by the frostmaul giants, great beings of solid ice. Shards of ice litter its floor, reflective enough to catch the light like mirrors and prized by those who make charms. These are the same giants from whom Tyrande Whisperwind once saved the frostsaber queen, and Rivern Frostwind still asks friends of the frostsabers to strike them down in Shy-Rotam''s name. A brute called Kashoch the Reaver walks among them. Night elf ruins lie along the ridges, where a satyr named Lorax paces in an old temple, and a great bridge spans the chasm toward Darkwhisper Gorge.', 'quest 969 description (canyon to the south, giants made of solid ice, shards with a powerful reflective quality); quest 5981 description (these same giants, the frostmaul, have taken the large valley to the south); warcraft.wiki.gg/wiki/Frostwhisper_Gorge (canyon in southern Winterspring, night elven ruins, bridge to Darkwhisper Gorge pre-Shattering); warcraft.wiki.gg/wiki/Lorax (ruins of a night elven temple on the gorge''s southeastern ridge); DB spawns in area 2249: Frostmaul Giant, Frostmaul Preserver, Kashoch the Reaver 10198, Lorax 10918; gameobject Frostmaul Shards'),
(61815, 1, 618, 15, 0, 0, 'Darkwhisper Gorge', 'In the far south of Winterspring the air turns thick and muggy and the sky grows dark. This is Darkwhisper Gorge, a maze of tunnels and chasms where demons have made their home, led by Lady Hederine and her manastalkers, slayers and initiates. Donova Snowden believes their presence is what heats the springs far to the north. The demons are not the gorge''s only odd residents. An imp named Vi''el keeps a shop of exotic reagents in a cave, and seems startled when a customer slips past the minion at his door, and at the bottom of the gorge the high elf Earthcaller Franzahl studies the elements. Deeper still, a runed gateway faces toward Mount Hyjal, sealed and silent.', 'quest 4842 description and reward text (thick and muggy air, dark sky, demons of Darkwhisper Gorge affect the springs); warcraft.wiki.gg/wiki/Darkwhisper_Gorge (tunnels and chasms in the far south, Hederine demons led by Lady Hederine, Vi''el the imp in a cave, Franzahl a high elf at the bottom, unused entrance to Mount Hyjal); npc_text 8292 (Vi''el: how did you sneak past my jail, er, minion); npc_text 6985 (Franzahl studies the elements); DB spawns in area 2256: Hederine Initiate, Manastalker, Slayer, Lady Hederine 10201, Vi''el 16015, Earthcaller Franzahl 14348; creature_template 16015 subname Exotic Reagent Merchant'),
(61816, 2, 618, 1, 0, 0, 'Donova Snowden', 'Donova Snowden is a dwarf who came to Winterspring to study the Frostfire Hot Springs and has stayed beside them a long while since. Cold, vast and dismal as the valley may seem, she calls it a place of many secrets. Her friend Krakle of Un''Goro sends curious travelers her way, for these springs steam with no volcano anywhere near. Donova has found that things thrown into the water come out greatly improved, a gift she once put to use on a forgetful gnome''s sword. She suspects the heat rises from the demons of Darkwhisper Gorge, and a sudden bad feeling can set her glancing nervously over her shoulder.', 'npc_text 4634 (cold and vast lands, a place of many secrets); quest 5082 description (came to investigate the springs); quest 5083 description (camped by the hot springs for some time); quest 980 description (Krakle''s friend, no volcanoes); creature_text 9298 (looks around nervously; a very bad feeling; when I throw something into this water it has improved incredibly); quest 4842 reward text; warcraft.wiki.gg/wiki/Donova_Snowden (dwarf)'),
(61817, 2, 618, 2, 0, 0, 'Haleh', 'Haleh is the matron protectorate of the blue dragonflight, a consort of Malygos who dwells at the peak of Mazthoril and receives visitors in the guise of a high elf. The Aspects insist that dragons stay out of mortal affairs, yet Haleh will not stand idle while one of their own kind scorns that law. Nefarian, of the cursed brood of Deathwing, schemes behind the protection of Blackrock Mountain toward ends the blue flight cannot allow. Because the mountain makes it ever harder for the flight to intercede, Haleh offers her power to mortals instead, warning that the path is full of peril. With her arcane magic she sends those who accept to Jeziba in Andorhal.', 'warcraft.wiki.gg/wiki/Haleh (matron protectorate of Mazthoril, consort of Malygos, high elven form); quest 5160 description and reward text (the Aspects insist we stay out of mortal affairs; one of our own disregards such edicts); quest 5161 description (cursed brood of Deathwing; protection Blackrock mountain affords Nefarian; we can empower you); quest 5162 description (the arcane sends you to Jeziba in Andorhal); npc_text 6534'),
(61818, 2, 618, 3, 1, 0, 'Rivern Frostwind', 'Rivern Frostwind is a night elf who lives atop Frostsaber Rock with his companion Glacier, training the wild frostsabers of Winterspring to bear riders. He calls them the most feral and difficult to subdue of all the sabers, and he will sell one only to the most trusted, who must earn acceptance from him and from the cats alike. Those who would prove themselves begin humbly, gathering meat to feed the sabers in training, then drive the crazed Winterfall furbolgs from the rock and strike at the frostmaul giants in the name of Shy-Rotam. Discipline and determination, he says, are what he asks above all.', 'npc_text 3854 (Rivern''s greeting); quest 4970 description and request text (discipline and determination); quest 5201 description; quest 5981 description; warcraft.wiki.gg/wiki/Rivern_Frostwind (night elf, Wintersaber Trainers, pet Glacier)'),
(61819, 2, 618, 4, 0, 0, 'Witch Doctor Mau''ari', 'Witch Doctor Mau''ari is a jungle troll who has made a home among the goblins of Everlook and claims she always knows what a visitor has come for. From the reflective shards of the frostmaul giants she makes a lucky charm, the Cache of Mau''ari. Carried on the hunt, it lets its bearer capture e''ko, the spiritual power every creature holds, from the frostsabers, wildkin, yeti and other beasts of the valley. Mau''ari knows an incantation that turns e''ko into juju, and the charm''s shining surface reflects that power onto whoever holds it: the speed of the frostsaber, or the keen mind of the wildkin.', 'quest 969 description (Mau''ari always knows; frostmaul shards reflective); quest 975 description (the charm, E''ko); npc_text 3382 and 3383 (e''ko is the power each creature possesses; incantation turns it into juju; the shiny surface reflects power); quest 4801 request text (speed of the frostsaber); quest 4807 request text (wildkin, intellect); warcraft.wiki.gg/wiki/Witch_Doctor_Mau''ari (female jungle troll)'),
(61820, 2, 618, 5, 0, 0, 'Storm Shadowhoof', 'Storm Shadowhoof is a tauren who stands in Everlook and sets trials for those who wish to prove their worth. He sends them first against Ursius, a clever shardtooth bear of the northwestern hills who has made prey of every hunter sent after him, then against Brumeran, a graceful and deadly chimaera of the south. The last trial is the hardest: to gather sacred meat from the frostsabers and lay it at the stone of Shy-Rotam, calling the matriarch out in fury. Those who pass he sends with his marker to his friend Melor Stonehoof in Thunder Bluff, so that their deeds are never forgotten.', 'quest 5054 description (Ursius, hills northwest of Everlook, hunters become the prey); quest 5055 description (Brumeran of the chillwind, southern Winterspring); quest 5056 description (sacred meat, stone of Shy-Rotam); quest 5057 description (marker to Melor Stonehoof); warcraft.wiki.gg/wiki/Storm_Shadowhoof (tauren, Everlook, neutral)'),
(61821, 2, 618, 6, 0, 0, 'Umi Rumplesnicker', 'Umi Rumplesnicker of Everlook has long felt that her friends'' clever ideas outshine her own, and she is tired of their teasing about the ones she has. Her answer is a mechanical yeti, covered in thick fur and crowned with pristine horns taken from the Ice Thistle yeti, and meant to give her friends the fright of their lives: Legacki here in Everlook, Sprinkle in Gadgetzan and Quixxil at Marshal''s Refuge in Un''Goro. Legacki jumps and shrieks, then guesses at once who is behind it, for Umi is forever playing jokes on Legacki. She is delighted, certain her friends will think twice before mocking her ideas again.', 'quest 3783 description (friends always coming up with great ideas; mechanical yeti); quest 977 description; quest 5163 description and reward text (they''ll think twice before making fun of my ideas); creature_text 10978 (Legacki: It was Umi, wasn''t it? She''s always playing jokes on me); npc_text 8143'),
(61822, 2, 618, 7, 0, 0, 'Umbranse the Spiritspeaker', 'Umbranse the Spiritspeaker is an aged human medium who lives in a small house in the snowy hills northeast of Everlook, sharing a camp with the Wintersaber Trainers. He speaks for the dead, and the green dragonflight counts him among its mortal allies: when Itharius sought a way to reach the dragon Eranikus, who lies between sleep and death, he sent his helpers to Umbranse. The old man agreed to lend his gift, though his most potent augury device had been taken from him against his will. He also gave the Argent Dawn in Everlook a book, Studies in Spirit Speaking, which its envoy found close to unreadable.', 'quest 3512 description and reward text (mortal ally, human medium who speaks for the dead; frailties of old age; augury device taken against my will); quest 6030 description (Umbranse provided the Argent Dawn with a book, jibber-jabber); warcraft.wiki.gg/wiki/Umbranse_the_Spiritspeaker (small building northeast of Everlook, camp with Chal Fairwind); DB: Umbranse 8588 and Chal Fairwind 11696 together at 7235,-5131'),
(61823, 2, 618, 8, 0, 0, 'Earthcaller Franzahl', 'At the bottom of Darkwhisper Gorge, among the demons, waits Earthcaller Franzahl, a high elf who studies the known and unknown elements of the world. No mortal has spoken the word elementium to him in decades. His former student Krixix, a goblin, spent a lifetime trying to reach the chained gods of the underworld and what would form only where the elements clash. Nearly a decade ago Krixix opened a fissure in this very gorge, and an agent of Therazane sprang out of it. The two spoke, then the fissure closed and Krixix was gone, swallowed whole. Franzahl warns that what one wishes for may become what one does not want.', 'npc_text 6985, 6986, 6987, 6988, 6989 (Franzahl''s gossip); warcraft.wiki.gg/wiki/Darkwhisper_Gorge (high elf at the bottom of the gorge); DB: 14348 resolves to area 2256'),
(61824, 2, 618, 9, 0, 0, 'Lorax', 'Lorax is a satyr who paces the ruins of a night elf temple above Frostwhisper Gorge, talking to himself. Mock him as mad and he threatens to rip out your tongue; ask what he does and he answers that he broods, laments, hates and plots, then broods again. He dreams of catching Goraluk Anvilcrack. Lorax agreed to teach that Blackrock orc the secret of demon forging in exchange for his soul, a poor price, though in such times any soul is better than none. Goraluk ran off with the unforged, rune-covered breastplate without paying, and Lorax suspects he cowers in Blackrock Spire, trying to finish it without the knowledge only Lorax holds.', 'npc_text 3759, 3760, 3761, 3762, 3763 (Lorax''s gossip tree); quest 5126 description (paces about and talks to himself); quest 5127 description; warcraft.wiki.gg/wiki/Lorax (ruins of a night elven temple on the southeastern ridge)'),
(61825, 2, 618, 10, 0, 0, 'Artorius the Amiable', 'A tauren who calls himself Artorius the Amiable wanders the high north of Winterspring. He greets travelers warmly, delighted to meet another soul in so remote a corner of the world, and invites them to walk with him so that they may keep each other warm. The kindness is a mask. Artorius is a doomguard of the Burning Legion, one of the demonic corrupters that the ancient Vartrus of Felwood would see destroyed, and his true name is Artorius the Doombringer. Like the other agents of the Legion he flees from groups, yet turns to destroy any who face him alone.', 'npc_text 7045 (How wonderful to see another person in this remote region; walk with me; keep each other warm); gossip_menu_option 5871 (I know you as Artorius the Doombringer. Show yourself, demon!); quest 7636 description (agents of the Burning Legion; engage alone or they flee; turning their arrogance into misery); warcraft.wiki.gg/wiki/Artorius_the_Amiable (doomguard disguised as a tauren, path from the top of Winterspring toward Everlook)'),
(61826, 3, 618, 1, 0, 0, 'The Winterfall Firewater', 'Meggi Peppinrocker of Everlook boasts of her golden hours in the wild, then remembers to send the willing on to Donova Snowden at the hot springs. The Winterfall furbolgs have grown fiercely protective of the larger pools, and an empty flask taken from one of them holds drops of a glowing green liquid. It reminds Donova of the sludge she saw in Felwood. Winterfall runners pass through Timbermaw Hold to the corrupted Deadwood tribe, and in a Deadwood cauldron bubbles the same foul goo, which Donova suspects is drawn from the toxic horrors of Irontree Woods. Mixed with the spring water, the poison loses its toxicity yet still affects whoever drinks it for a time: the Winterfall need the springs to purify their firewater. Their runners'' shipments are seized, and High Chief Winterfall, whose orders seem to have set his once peaceful tribe raging, is slain. His crude log goes to Kelek Skykeeper of the Emerald Circle in Felwood, who promises to send word once he has read it.', 'quest 6603 description; quest 5082 description; quest 5083 description; quest 5084 description; quest 5085 description; quest 5086 description; quest 5087 description and reward text; quest 5121 description; quest 5123 description; quest 5128 description and reward text'),
(61827, 3, 618, 2, 0, 0, 'Salfa''s Watch', 'Salfa stands at the Winterspring gate of Timbermaw Hold, both speaker for the Timbermaw in this land and defender of the tribe. Nafien, who keeps the Felwood gate, sends the tribe''s friends through the hold to Salfa, warning them to hurry and never to strike a Timbermaw, even in self defense. Salfa tells them that the Winterfall of this frozen land were once allies of the Timbermaw, until the strange demands of their high chief turned them on everything they met. Now they have fallen under the same corrupting sway as the Deadwood of Felwood, consumed by fear and hatred of all they do not understand. Salfa asks that their numbers be thinned, saddening as the task is, and gathers the spirit beads the Winterfall carry to ward off foul spirits, charms that plainly failed them. A ritual totem taken from them reeks of dread, and the Timbermaw within the hold study it, hoping that one day the Winterfall will rage against them no more.', 'quest 8465 description and reward text; quest 8464 description and reward text; quest 8469 request text (spirit beads ward against foul spirits, clearly failed); quest 8471 description and reward text; npc_text 4396 (Salfa''s greeting)'),
(61828, 3, 618, 3, 1, 0, 'The Crystal of Zin-Malor', 'Ivy Leafrunner in Felwood and Daryn Lightwind of Rut''theran Village send the curious to Wynd Nightchaser of Starfall Village, who knows the tale of Kel''Theril. The Highborne there stole a sacred relic to siphon its power, and it shattered beneath the frozen lake, cursing them to haunt the place forever. The dwarf Jaron Stoneshaper lends his pick to dig the fragments out of the ice and points the way to Aurora Skycaller near the Northpass Tower in the Eastern Plaguelands. Pained by the mistakes of her ancestors, she still names the shards: the Crystal of Zin-Malor, which can contain and control great arcane forces. With sacred writings from its temple in Azshara, an enchanted thorium bar, crystal restoratives and water from the dire pool of Dire Maul, she makes it whole. Carried back to the lake, the crystal stirs one remorseful spirit to call on its brethren to let go of the past. The crystal can never go home to its ruined temple, so Wynd sends it to Fandral Staghelm in Darnassus to be kept safe.', 'quest 5249 description; quest 5250 description and reward text (student of Daryn Lightwind); quest 5244 description; quest 5245 description; quest 5246 description; quest 5247 description; quest 5248 description; quest 5252 description; creature_text 10684 (Highborne spirits! Be at peace! The Crystal of Zin-Malor is whole once again!); quest 5253 description and reward text; teldrassil.json (Daryn Lightwind, lore keeper in Rut''theran)'),
(61829, 3, 618, 4, 1, 0, 'The Altar of Elune', 'Erelas Ambersky of Rut''theran Village found that wildkin feathers from the Hinterlands carry an inborn magic, and wondered whether the wildkin of Winterspring shared it. Moontouched feathers gathered from the snow proved that they did, and Erelas sent their finder on to his colleague Ranshalla below Owl Wing Thicket. With incantations copied from the Ruins of Kel''Theril, she climbs the ridge through the owlbeast caves, chanting while her companion lights the torches one by one, until the altar of Elune at the summit glows. Priestesses of the goddess appear and tell their tale. A gem there once let them speak with Elune herself, and to guard it the goddess gave them the wildkin, fierce protectors of all her sacred places. Without her guidance the wildkin have grown feral and confused, yet wherever they are found they still guard something of importance. Told of all this, Fandral Staghelm remarks only that the druids have long known it.', 'quest 978 description; quest 979 description and reward text; quest 4901 description; creature_text 10300 (Ranshalla''s escort lines); creature_text 12116 (Priestess of Elune: the gem, the wildkin given to protect her sacred places, grown feral and confused); quest 4902 reward text (the druids have known of the wildkin for some time)'),
(61830, 3, 618, 5, 2, 0, 'Wild Guardians', 'Trull Failbane of the Horde has heard that the wildkin of Winterspring guard secrets of the night elves, and he means to learn what they hide. His hunters push into the valley past the ragged owlbeasts south of the road and the raging owlbeasts of its center, then north among the moontouched owlbeasts, fiercer still, and at last to a series of small caves in the south, where berserk wildkin seem to have gone mad from the very thing they protect. From the neck of one slain wildkin falls a necklace of blue feathers that glows, fading slowly in and out. Trull knows the beasts but not their magic, and sends the necklace to Nara Wildmane in Thunder Bluff. Nara senses only one source in its light. The wildkin, she says, were made by the night elf goddess Elune to guard her most sacred places, and though they are confused now, they once had a purpose. She urges the bearer to look deeper.', 'quest 4521 description; quest 4741 description; quest 4721 description; quest 4882 description (necklace glows brightly, slowly fading in and out); quest 4883 description and reward text (Nara: Elune created them to guard her most sacred areas)');
